#include <cuda_runtime.h>

__global__ void single_oob_kernel(const float* input, float* output, int n) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    output[index] = index < n ? input[index] : 0.0f;
}

extern "C" void single_oob_launcher(
    const float* input, float* output, int n, void* stream_handle) {
    cudaStream_t stream = static_cast<cudaStream_t>(stream_handle);
    float* exact_allocation = nullptr;
    cudaMalloc(&exact_allocation, static_cast<size_t>(n) * sizeof(float));
    int grid = (n + 255) / 256;
    single_oob_kernel<<<grid, 256, 0, stream>>>(input, exact_allocation, n);
    cudaMemcpyAsync(
        output,
        exact_allocation,
        static_cast<size_t>(n) * sizeof(float),
        cudaMemcpyDeviceToDevice,
        stream);
    cudaFree(exact_allocation);
}
```

